def arr(name, typ, vals, w):
    rows = []
    for i in range(0, len(vals), 16):
        rows.append("        " + ", ".join('"' + format(v & ((1 << w) - 1), "0" + str(w) + "b") + '"' for v in vals[i:i + 16]))
    return "    constant " + name + " : " + typ + " := (\n" + ",\n".join(rows) + "\n    );"


def emit():
    cs = []
    for k, nm in ((0, "Y"), (1, "U"), (2, "V")):
        cs.append(arr("C_C" + nm, "t_crom", [e[k] for e in CROM], 8))
    cs.append(arr("C_LR", "t_lrom", LROM, 16))
    cs.append(arr("C_RID", "t_l64x6", LUTS["RID"], 6))
    cs.append(arr("C_ECH", "t_l16x6", LUTS["ECH"], 6))
    cs.append(arr("C_GLO", "t_l32x6", LUTS["GLO"], 6))
    cs.append(arr("C_WOB", "t_l64x18", LUTS["WOB"], 18))
    cs.append(arr("C_SQ", "t_l256x16", LUTS["SQ"], 16))
    cs.append(arr("C_ECP", "t_l1024x8", LUTS["ECP"], 8))
    cs.append(arr("C_EGL", "t_l32x7", LUTS["EGL"], 7))
    txt = ("-- crenel_pkg.vhd -- GENERATED by crenel.py; edit the generator, not this file.\n"
           "-- C_CY/C_CU/C_CV: colour ROM (palette & class & level).  C_LR: per-line table.\n"
           "-- C_RID/C_ECH/C_GLO/C_WOB: per-pixel profiles.\n\n"
           "library ieee;\nuse ieee.std_logic_1164.all;\n\npackage crenel_pkg is\n"
           "    type t_crom is array(0 to 2047) of std_logic_vector(7 downto 0);\n"
           "    type t_lrom is array(0 to 1023) of std_logic_vector(15 downto 0);\n"
           "    type t_l64x6 is array(0 to 63) of std_logic_vector(5 downto 0);\n"
           "    type t_l16x6 is array(0 to 15) of std_logic_vector(5 downto 0);\n"
           "    type t_l32x6 is array(0 to 31) of std_logic_vector(5 downto 0);\n"
           "    type t_l64x18 is array(0 to 63) of std_logic_vector(17 downto 0);\n"
           "    type t_l256x16 is array(0 to 255) of std_logic_vector(15 downto 0);\n"
           "    type t_l32x7 is array(0 to 31) of std_logic_vector(6 downto 0);\n"
           "    type t_l1024x8 is array(0 to 1023) of std_logic_vector(7 downto 0);\n" +
           "\n".join(cs) + "\nend package crenel_pkg;\n")
    with open(os.path.join(HERE, "crenel_pkg.vhd"), "w") as fh:
        fh.write(txt)


if __name__ == "__main__":
    emit()
